from core import *

def strip(w,h,t):
 s=min(260/w,160/h);x=65;y=30
 return svg(f'<rect x="{x}" y="{y}" width="{w*s}" height="{h*s}" fill="white"/><polygon points="{x},{y+(h-t)*s} {x+(w-t)*s},{y} {x+w*s},{y} {x+w*s},{y+t*s} {x+t*s},{y+h*s} {x},{y+h*s}" fill="#d8bb66"/>'+text(x+w*s/2,y+h*s+24,f'{w} cm')+text(x+w*s+29,y+h*s/2,f'{h} cm')+text(x+t*s/2,y+h*s-7,f'{t}')+text(x+(w-t/2)*s,y+18,f'{t}'),label='Rectangle with diagonal strip. Matching corner offsets are labelled in centimetres.')

def papers():
 p=[]
 p.append(item('Calculate 83.2 − 37.35.','45.85','Write 83.2 as 83.20 so the decimal places align. Subtract 37.35 to obtain 45.85. Check that 45.85+37.35=83.20.','DIG-01',['45.15','45.95','46.85','54.85']))
 p.append(item('Thirty-six children of different ages stand from youngest to oldest. Ava is ninth youngest and Sam is twelfth oldest. How many children stand between them?',15,'Convert Sam to the same ranking direction: 36−12+1=25th youngest. The positions strictly between 9 and 25 number 25−9−1=15.','COUNT-01',[13,14,16,17],check=(36-12+1)-9-1))
 p.append(item('A cyclist trains twice daily for 12 days, spending 18 hours training altogether. Each ride lasts equally long. How many minutes does one ride last?',45,'There are 2×12=24 rides. Eighteen hours is 1080 minutes, so each ride lasts 1080÷24=45 minutes.','RATE-01',[30,36,48,60],check=18*60//24))
 p.append(item('Among 87 students, 56 join music and 49 join sport. Eight join neither. How many join sport but not music?',23,'The union has 87−8=79 students. The overlap is 56+49−79=26. Sport only therefore has 49−26=23 students.','COUNT-04',[15,26,30,38],check=87-8-56))
 p.append(item('A gardener places 3 seeds in the first pot, then twice as many in each next pot. Six pots are filled, and 5 seeds remain unused. How many seeds did the gardener begin with?',194,'The pots contain 3,6,12,24,48,96 seeds, totalling 189. Add the five unused seeds to recover the starting total of 194.','SEQ-02',[189,191,197,386],check=sum(3*2**k for k in range(6))+5))
 p.append(item('The letters stand for fixed numbers. The table shows three sums. What is A+B+C?',19,'Add the three equations. Every letter appears three times, giving 3(A+B+C)=14+21+22=57. Divide by three to find 19. Individual values are unnecessary.','LOGIC-03',[17,18,20,21],check=(14+21+22)//3,figure=table_diagram([['A+A+B',14],['B+B+C',21],['C+C+A',22]],['Expression','Total'])))
 p.append(item('The digits 1, 2, 3, 4 and 5 are used once each in a five-digit number. The first and last digits must be even. How many numbers are possible?',12,'The two even digits, 2 and 4, occupy the ends in 2 ways. The three odd digits fill the middle positions in 3×2×1=6 ways. Multiply to obtain 12.','COUNT-02',[6,18,24,36],check=2*math.factorial(3)))
 p.append(item('What is the units digit of 9²⁰²⁷ + 7²⁰²⁶?',8,'An odd power of 9 ends in 9. Powers of 7 cycle 7,9,3,1; exponent 2026 leaves remainder 2 modulo 4, so that term ends in 9. Their sum ends like 9+9=18, hence 8.','DIV-05',[0,2,6,9],check=(pow(9,2027,10)+pow(7,2026,10))%10))
 p.append(item('Starting with Thursday 11 March, find the day one day earlier than the day four days later than the day one week earlier than the day two days later.','Tuesday 9 March','Work from the starting day outward: +2,−7,+4,−1. The net change is −2 days. Two days before Thursday 11 March is Tuesday 9 March.','ALG-04',['Monday 8 March','Wednesday 10 March','Friday 12 March','Saturday 13 March']))
 p.append(item('Three taps can separately fill a tank in 8, 12 and 24 hours. Their rates are constant. How many hours do they take together?',4,'In one hour the taps fill 1/8+1/12+1/24=3/24+2/24+1/24=1/4 of the tank. A whole tank therefore takes 4 hours.','RATE-02',[3,5,6,8],check=int(1/(F(1,8)+F(1,12)+F(1,24)))))
 p.append(item('A clock shows 6 pm. What will it show 2501 hours later?','11 pm','A 24-hour day does not change the displayed time. Since 2501=104×24+5, only the extra five hours matter. Five hours after 6 pm is 11 pm.','DIV-05',['1 am','5 am','7 pm','9 pm']))
 p.append(item('Parking costs $7 for the first two hours and $3 for each additional half-hour or part of a half-hour. What is the charge for 3 hours 10 minutes?','$16','The extra time after two hours is 70 minutes. It occupies three charged half-hour blocks, because even the final 10 minutes uses a block. Total cost is 7+3×3=$16.','RATE-01',['$13','$14','$15','$19']))
 p.append(item('An 8 cm by 6 cm rectangle is joined to a 5 cm by 6 cm rectangle along one whole 6 cm side. What is the perimeter of the combined shape?', '38 cm','The two perimeters total 28+22=50 cm. The shared 6 cm side is internal and was counted twice, so subtract 12 to get 38 cm. Equivalently, the result is a 13 cm by 6 cm rectangle.','GEO-01',['26 cm','32 cm','44 cm','50 cm']))
 p.append(item('A machine multiplies an input by a fixed whole number and then adds another fixed whole number. Input 7 gives 35; input 15 gives 67. What does input 11 give?',51,'The input rises by 8 while output rises by 32, so the multiplier is 4. The added number is 35−4×7=7. Input 11 therefore gives 4×11+7=51.','ALG-03',[44,47,55,59],check=4*11+7))
 p.append(item('Five candidates receive 604 votes in total. The winner leads the other candidates by 25, 37, 41 and 53 votes. How many votes does the winner receive?',152,'If the winner has w votes, the others total 4w−25−37−41−53. Thus 5w−156=604, so 5w=760 and w=152. Check the other counts are 127,115,111,99.','ALG-05',[124,144,150,156],check=(604+25+37+41+53)//5))
 p.append(item('A 10 cm by 6 cm rectangle contains the diagonal shaded strip shown. Each marked corner offset is 2 cm. What fraction of the rectangle is shaded?','7/15','The two unshaded right triangles each have perpendicular legs 8 cm and 4 cm. Their combined area is 2×8×4÷2=32 cm². The rectangle area is 60 cm², leaving shaded area 28 cm². The fraction is 28/60=7/15.','GEO-02',['2/5','8/15','3/5','7/10'],check=str(F(60-8*4,60)),figure=strip(10,6,2)))
 p.append(item('A 120 cm wire runs from left to right, never backtracking horizontally. It makes a downward-and-return detour 5 cm deep and an upward-and-return detour 8 cm high. Every segment is horizontal or vertical. What is the horizontal distance between its ends?', '94 cm','The vertical segments use 2×5+2×8=26 cm. All remaining wire is horizontal and moves right, so the horizontal distance is 120−26=94 cm.','GEO-01',['81 cm','86 cm','102 cm','107 cm']))
 p.append(item('A number consists of eighteen digits, all 1. From it subtract the nine-digit number 222222222. What is the sum of the digits in the answer?',81,'Subtraction gives 111111110888888889. This has eight 1s, one 0, eight 8s and a final 9. The digit sum is 8+64+9=81. The borrowing pattern is easier to track than treating all eighteen columns separately.','DIG-04',[72,80,82,90],check=sum(map(int,str(int('1'*18)-int('2'*9))))))
 p.append(item('Thirty couples attend a picnic. One third bring no children, one third bring two children and one third bring three children. How many people attend?',110,'The adults number 30×2=60. Each third contains ten couples, so there are 10×0+10×2+10×3=50 children. Total attendance is 60+50=110.','FRAC-04',check=30*2+10*5))
 p.append(item('Three indicator lights flash every 6, 10 and 15 seconds. They flash together now. How many seconds pass before their next simultaneous flash?',30,'A simultaneous flash occurs at a common multiple of the three intervals. Their least common multiple is 2×3×5=30. Check 30 is divisible by all three intervals.','DIV-02',check=math.lcm(6,10,15)))
 p.append(item('A and B are different nonzero digits. The three-digit numbers ABA and BAB satisfy ABA−BAB=273. What is the greatest possible value of ABA?',969,'Use place value: ABA=101A+10B and BAB=101B+10A. Their difference is 91(A−B)=273, so A−B=3. To maximise ABA choose the largest A, namely 9, and then B=6. This gives 969−696=273.','DIG-05',check=max(101*a+10*b for a in range(1,10) for b in range(1,10) if 91*(a-b)==273)))
 p.append(item('A cake is 7 unit cubes wide, 5 deep and 4 high. Icing covers the top and all four vertical sides, but not the bottom. How many unit cubes receive icing?',95,'There are 7×5×4=140 cubes. Uniced cubes avoid the two width sides, the two depth sides and the top, giving (7−2)(5−2)(4−1)=45. The iced count is 140−45=95.','SOLID-02',check=7*5*4-(7-2)*(5-2)*(4-1),figure=cuboid(7,5,4)))
 p.append(item('A traveller spent one fifth of her life in Japan, one third in Canada and one quarter in France. The remaining 13 years were in Australia. How old is she?',60,'The listed fractions add to 12/60+20/60+15/60=47/60. The remaining 13/60 equals 13 years, so one sixtieth equals one year and the whole life is 60 years.','FRAC-01',check=int(F(13)/(1-F(1,5)-F(1,3)-F(1,4)))))
 one=paper('rossmoyne',1,p)
 p=[]
 p.append(item('Calculate 8.4 × 2.5.',21,'Multiplying by 2.5 is multiplying by 10 and dividing by 4. Thus 8.4×2.5=84÷4=21.','DIG-01',[20.1,20.5,22,210],check=8.4*2.5))
 p.append(item('There are 41 runners. Each has a different finishing time. Ari finishes 16th and Bo finishes 11th from last. How many runners finish after Ari but before Bo?',14,'Bo is 41−11+1=31st. The positions after 16th and before 31st are 17th through 30th, giving 31−16−1=14.','COUNT-01',[13,15,16,25],check=41-11+1-16-1))
 p.append(item('A bottle-filling machine fills four bottles each minute. It works for 15 minutes every hour over a six-hour shift. How many bottles does it fill?',360,'The machine runs for 15×6=90 minutes, not all 360 minutes of the shift. At four bottles per running minute it fills 4×90=360 bottles.','RATE-01',[90,240,1440,2160],check=4*15*6))
 p.append(item('Seventy-nine children each join chess or drama or both. Fifty-two join chess and forty-three join drama. How many join exactly one club?',63,'The overlap is 52+43−79=16. The remaining 79−16=63 children belong to exactly one club.','COUNT-04',[16,27,36,68],check=2*79-52-43))
 p.append(item('A display has rows of 15, 20, 25, …, 60 flags. How many flags are displayed?',375,'There are (60−15)÷5+1=10 rows. Pair the first and last rows to make 75 flags; five such pairs give 5×75=375.','SEQ-01',[330,350,360,400],check=sum(range(15,61,5))))
 p.append(item('Three identical triangles balance two identical squares. One square balances six identical circles. How many circles balance one triangle?',4,'Two squares balance twelve circles. Since three triangles balance those same two squares, each triangle balances 12÷3=4 circles.','ALG-02',[3,6,9,12],check=2*6//3))
 p.append(item('Five different books are arranged on a shelf. The two maths books must be next to each other. How many arrangements are possible?',48,'Treat the maths books as one block. Arrange this block with the other three books in 4!=24 ways, then order the maths books inside the block in 2 ways. Total 48.','COUNT-03',[24,36,60,120],check=2*math.factorial(4)))
 p.append(item('What is the last digit of 2⁴⁵ × 8¹³?',6,'Powers of 2 repeat 2,4,8,6, so exponent 45 gives 2. Powers of 8 repeat 8,4,2,6, so exponent 13 gives 8. The product ends like 2×8=16, hence 6.','DIV-05',[2,4,8,0],check=pow(2,45,10)*pow(8,13,10)%10))
 p.append(item('Two taps fill a tank separately in 6 hours and 9 hours. A drain empties a full tank in 18 hours. With all three operating at constant rates, how many hours does an empty tank take to fill?', '4.5','The net rate is 1/6+1/9−1/18=3/18+2/18−1/18=2/9 tank per hour. The time is its reciprocal, 9/2=4.5 hours.','RATE-02',['3','4','5','6']))
 p.append(item('It is 7 am on a 24-hour cycle. What time is it 1961 hours later?','Midnight','Since 1961=81×24+17, advance only 17 hours from 7 am. Twelve hours reaches 7 pm; another five reaches midnight.','DIV-05',['5 am','Noon','5 pm','11 pm']))
 p.append(item('A delivery company charges $18 for the first 8 kg and $5 for each additional 3 kg or part thereof. What does a 24 kg package cost?','$48','Beyond the first 8 kg there are 16 kg. That requires six blocks of up to 3 kg. The total charge is 18+6×5=$48.','RATE-01',['$43','$44','$45','$53']))
 p.append(item('The exterior angle at a vertex of a triangle is 124°. One of the two non-adjacent interior angles is 47°. What is the other?', '77°','An exterior angle equals the sum of the two opposite interior angles. Subtract 47° from 124° to obtain 77°. Equivalently, the adjacent interior angle is 56°, and 180−56−47=77.','GEO-03',['47°','56°','67°','87°']))
 p.append(item('A team earns 3 points for a win and 1 for a draw. In 12 games it has 6 wins and 3 losses. How many points does it earn?',21,'The remaining 12−6−3=3 games are draws. Points total 6×3+3×1=21. Losses contribute zero.','DATA-03',[18,20,24,27],check=6*3+(12-6-3)))
 p.append(item('A box has red and blue beads in the ratio 2:5. Twelve red beads are added, making the colour counts equal. How many beads were in the box at first?',28,'The original difference is three ratio parts and equals the twelve added beads. One part is four beads, so the initial seven parts contain 28 beads.','FRAC-02',[20,24,35,42],check=12//3*7))
 p.append(item('In a two-candidate election, the winner leads by 46 votes. If 18 votes were transferred from the winner to the loser, what would the new winning margin be?',10,'A transferred vote reduces the winner’s count by one and increases the loser’s by one, reducing the gap by two. Eighteen transfers reduce the gap by 36, leaving 46−36=10.','ALG-05',[8,18,28,36],check=46-2*18))
 p.append(item('A 12 cm by 8 cm rectangle has a right triangle removed from each of two opposite corners. Each removed triangle has perpendicular legs 3 cm and 4 cm. What fraction of the rectangle remains?','7/8','The rectangle area is 96 cm². Each triangle has area 3×4÷2=6, so 12 is removed. The remaining fraction is 84/96=7/8.','GEO-02',['3/4','5/6','11/12','15/16'],check=str(F(12*8-2*3*4//2,12*8))))
 p.append(item('A bent wire has length 160 cm. Its vertical segments total 32 cm. Its horizontal segments include 9 cm travelling left; all the other horizontal segments travel right. What is the net horizontal distance between its ends?', '110 cm','Horizontal wire totals 160−32=128 cm. Of this, 9 cm goes left and 119 cm right. The net horizontal displacement is 119−9=110 cm. Subtracting the leftward length twice accounts for the backtracking.','GEO-01',['101 cm','119 cm','128 cm','142 cm']))
 p.append(item('What is the sum of the digits of 10¹⁵ − 47?',125,'The result is 999999999999953: twelve 9s followed by 953. The digit sum is 12×9+9+5+3=125. Check 10¹⁵−1 has fifteen 9s; subtracting a further 46 changes its final two digits from 99 to 53.','DIG-04',[117,123,126,133],check=sum(map(int,str(10**15-47)))))
 p.append(item('Forty families each have two adults. Half the families have one child, one quarter have two children and the rest have three children. How many people are there?',150,'The adults total 80. Children number 20×1+10×2+10×3=70. Total people=80+70=150.','FRAC-04',check=40*2+20+10*2+10*3))
 p.append(item('The strings ABCABC, WXYZ and PQRST each rotate by moving their last character to the front once per second. How many seconds pass before all three first return to their starting strings together?',60,'ABCABC returns after 3 shifts because its block ABC repeats. WXYZ and PQRST have periods 4 and 5. The first common return is lcm(3,4,5)=60 seconds. Using the full length 6 for the repeated string would miss its shorter period.','DIV-02',check=math.lcm(3,4,5)))
 p.append(item('A and B are different nonzero digits. AB and BA are two-digit numbers with sum 154. Their digit product is 48. What is the larger of the two numbers?',86,'The sum is 11(A+B)=154, so A+B=14. The digit pair with sum 14 and product 48 is 6 and 8. The larger number is 86. Check 86+68=154.','DIG-05',check=max(10*a+b for a in range(1,10) for b in range(1,10) if 11*(a+b)==154 and a*b==48)))
 p.append(item('A block is 6 cubes wide, 5 deep and 4 high. Only its top, front and back faces are painted. How many unit cubes have no paint?',54,'Unpainted cubes may reach either width edge but must avoid the front and back layers and the top layer. There are 6 choices across, 5−2=3 in depth and 4−1=3 in height, giving 6×3×3=54.','SOLID-02',check=6*(5-2)*(4-1),figure=cuboid(6,5,4)))
 p.append(item('A library lends out one quarter of its books. It then lends out two fifths of the books still there. Finally it receives 18 returned books and has 126 books. How many books did it have initially?',240,'Before the returns, 126−18=108 books remained. The remaining fraction of the initial stock was (3/4)(3/5)=9/20. Thus the original count was 108×20÷9=240. Check: 240→180→108→126.','FRAC-01',check=int(F(126-18)/(F(3,4)*F(3,5)))))
 two=paper('rossmoyne',2,p)
 p=[]
 p.append(item('Calculate 12.6 ÷ 0.3.',42,'Multiply both dividend and divisor by ten to remove the decimal divisor: 12.6÷0.3=126÷3=42.','DIG-01',[4.2,37.8,40.2,420],check=126//3))
 p.append(item('In a line of 45 students, Noor is 12th from the front. She moves eight places towards the back. What is her new position from the back?',26,'Noor becomes 12+8=20th from the front. Her position from the back is 45−20+1=26th.','COUNT-01',[24,25,27,33],check=45-(12+8)+1))
 p.append(item('A pump transfers 1.8 litres each minute. It runs for 25 minutes and the water is shared equally among six buckets. How many litres go into each bucket?',7.5,'The pump transfers 1.8×25=45 litres altogether. Dividing among six buckets gives 45÷6=7.5 litres per bucket.','RATE-01',[6.5,7,8,10.8],check=1.8*25/6))
 p.append(item('Of 64 students, 38 cycle to school and 29 walk on at least one day each week. Fifteen do both during the week. How many do neither?',12,'The number doing at least one is 38+29−15=52, subtracting the double-counted overlap. The remaining 64−52=12 do neither.','COUNT-04',[3,9,15,18],check=64-(38+29-15)))
 p.append(item('A stack of trays contains 2 cups on the top tray, 6 on the next, 18 on the next, and three times as many on each further tray. There are five trays. How many cups are there?',242,'The five counts are 2,6,18,54,162. Their sum is 242. Checking the number of trays prevents adding an unwanted sixth term.','SEQ-02',[162,240,244,726],check=sum(2*3**k for k in range(5))))
 p.append(item('Two apples and one pear weigh 340 g. One apple and two pears weigh 380 g. What do three apples and three pears weigh?', '720 g','Add the two given collections. Together they contain exactly three apples and three pears, so their total mass is 340+380=720 g. Individual fruit masses are not needed.','ALG-03',['360 g','680 g','760 g','1080 g']))
 p.append(item('Four different cards are placed in a row. The red card must appear somewhere before the blue card. How many orders are possible?',12,'There are 4!=24 unrestricted orders. Swapping red and blue pairs each order with exactly one order having the opposite relative order. Half, or 12, have red before blue. They need not be adjacent.','COUNT-02',[6,8,16,24],check=math.factorial(4)//2))
 p.append(item('What is the remainder when 5³⁷ + 5³⁸ is divided by 6?',0,'Modulo 6, 5 behaves like −1. Its odd power leaves 5 and its even power leaves 1. The sum leaves 5+1=6, so the remainder is 0.','DIV-05',[1,2,4,5],check=(pow(5,37,6)+pow(5,38,6))%6))
 p.append(item('A date is three days after the day that is nine days before the day that is two weeks after Monday 8 June. What is the date?','Tuesday 16 June','Combine the offsets from 8 June: +14−9+3=+8 days. One week and one day after Monday 8 June is Tuesday 16 June.','ALG-04',['Sunday 14 June','Monday 15 June','Wednesday 17 June','Thursday 18 June']))
 p.append(item('Mia can pack a shipment in 5 hours and Leo in 10 hours. They work together for two hours, then Mia finishes alone. How many more hours does Mia need?',2,'Together they pack 1/5+1/10=3/10 per hour, so in two hours they pack 3/5. The remaining 2/5 takes Mia (2/5)÷(1/5)=2 hours.','RATE-02',[1,1.5,2.5,3],check=int((1-2*(F(1,5)+F(1,10)))/F(1,5))))
 p.append(item('A 24-hour clock shows 21:00. What will it show after 1729 hours?','22:00','Since 1729=72×24+1, the whole days return the clock to 21:00 and the extra hour gives 22:00.','DIV-05',['01:00','09:00','20:00','23:00']))
 p.append(item('A taxi charges $6 initially plus $4 for each kilometre or part of a kilometre. What is the charge for a 7.2 km journey?','$38','A distance of 7.2 km uses eight charged kilometre blocks. The fare is 6+8×4=$38. Rounding down would leave the final part of the journey uncharged.','RATE-01',['$28.80','$34','$34.80','$42']))
 p.append(item('Three identical squares of side 4 cm form a straight row, sharing complete sides. What is the perimeter of the resulting shape?', '32 cm','The row is a 12 cm by 4 cm rectangle, so its perimeter is 2(12+4)=32 cm. Alternatively, subtract four copies of the shared 4 cm edges from the three separate square perimeters.','GEO-01',['24 cm','28 cm','40 cm','48 cm']))
 p.append(item('A machine’s rule is multiply by a fixed number and then subtract a fixed number. Input 5 produces 23 and input 9 produces 43. What input produces 68?',14,'A four-unit input change creates a twenty-unit output change, so the multiplier is 5. The rule is 5x−2. Solving 5x−2=68 gives 5x=70 and x=14.','ALG-03',[12,13,15,16],check=(68+2)//5))
 p.append(item('Four teams score a total of 398 points. The leading team is 18, 26 and 38 points ahead of the other teams. How many points did it score?',120,'Let the leader score w. The total is 4w−18−26−38=398. Thus 4w=480 and w=120. The other scores 102,94,82 total 278, confirming the overall 398.','ALG-05',[100,110,118,128],check=(398+18+26+38)//4))
 p.append(item('A 9 cm by 7 cm rectangle has the diagonal strip shown, with 1 cm offsets at the marked corners. What is the shaded area?', '15 cm²','The whole rectangle has area 63 cm². The two unshaded triangles each have perpendicular legs 8 and 6 cm; together they have area 8×6=48 cm². The shaded area is 63−48=15 cm².','GEO-02',['12 cm²','14 cm²','16 cm²','21 cm²'],figure=strip(9,7,1)))
 p.append(item('A rectangular frame is 30 cm wide and 20 cm high. A straight diagonal brace connects opposite corners. What is the sum of the lengths of the four outer edges and two further horizontal braces, each spanning the full width?', '160 cm','The four outer edges total 2(30+20)=100 cm. The two horizontal braces add 2×30=60 cm. The diagonal brace is mentioned but is not one of the requested lengths. The required sum is 160 cm.','GEO-01',['100 cm','140 cm','180 cm','200 cm']))
 p.append(item('A number consists of twelve digits, all 9. It is multiplied by 7. What is the sum of the digits of the product?',108,'The number is 10¹²−1. Multiplication gives 7×10¹²−7=6999999999993: a leading 6, eleven 9s and a final 3. The digit sum is 6+11×9+3=108.','DIG-04',[99,102,109,117],check=sum(map(int,str(int('9'*12)*7)))))
 p.append(item('At a camp, 18 tents each hold two adults. Six tents also hold one child, seven hold two children and the remaining tents hold three children. How many people are there?',71,'There are 36 adults. Five tents remain after the groups of six and seven. Children total 6×1+7×2+5×3=35. Total people=36+35=71.','FRAC-04',check=18*2+6+7*2+(18-6-7)*3))
 p.append(item('Three trains leave a station every 14, 21 and 35 minutes. They leave together at 8 am. How many minutes after 8 am will they next leave together?',210,'The prime factors required are 2,3,5,7. Their product is 210, the least common multiple of 14,21,35. No smaller interval contains all required factors.','DIV-02',check=math.lcm(14,21,35)))
 p.append(item('A and B are different nonzero digits. The three-digit number AAB plus the two-digit number BA equals 499. What is AAB?',445,'Place value gives 111A+11B=499. Modulo 11, this says A leaves remainder 4, so A=4. Then 444+11B=499 gives B=5. Therefore AAB=445, and 445+54=499.','DIG-05',check=next(110*a+b for a in range(1,10) for b in range(1,10) if a!=b and 111*a+11*b==499)))
