 p.append(item('A tank is three tenths full. Adding 45 litres makes it three quarters full. What is its full capacity in litres?',100,'The added fraction is 3/4−3/10=15/20−6/20=9/20. If 9/20 equals 45 litres, one twentieth equals 5 litres. The whole tank holds 20×5=100 litres.','FRAC-01',check=int(F(45)/(F(3,4)-F(3,10)))))
 return [one,two,paper('rossmoyne',3,p)]
